$ErrorActionPreference='Stop'
$runtime=(Resolve-Path (Join-Path $PSScriptRoot '..\scripts\organizer.ps1')).Path
$base=Join-Path ([IO.Path]::GetTempPath()) ('do-contract-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory $base
$script:pass=0;$script:fail=0;$script:skip=0
function Assert($condition,[string]$name){if($condition){$script:pass++;Write-Host "PASS $name"}else{$script:fail++;Write-Host "FAIL $name"}}
function Read-Envelope($json){$o=ConvertFrom-Json -InputObject $json;if($o.schemaVersion -ne 1 -or $null -eq $o.items -or $o.count -ne $o.items.Count){throw 'Contract violation: count/items mismatch'};return $o}
function Make-Fixture([string]$name,[string[]]$files){$p=Join-Path $base $name;$null=New-Item -ItemType Directory $p;foreach($file in $files){'sample'|Set-Content (Join-Path $p $file)};return $p}
try {
 Write-Host "PowerShell $($PSVersionTable.PSVersion); runtime=$runtime"
 foreach($n in @(0,1,3)){$names=@('a.pdf','b.exe','c.gguf')|Select-Object -First $n;$dir=Make-Fixture "scan$n" $names;$json=& $runtime -Command Scan -Source $dir;$envl=Read-Envelope $json;Assert ($envl.operation -eq 'Scan' -and $envl.count -eq $n -and $envl.items.Count -eq $n) "Scan $n items; type=$($envl.GetType().FullName); count=$($envl.count)";$round=Read-Envelope ($envl|ConvertTo-Json -Depth 8);Assert ($round.items.Count -eq $n) "Scan JSON roundtrip $n"}
 $classDir=Make-Fixture classify @('app.exe','doc.docx','sheet.xlsx','archive.zip','github-source.zip','model.gguf','weights.safetensors','photo.png','audio.mp3','video.mp4','unknown.bin','incomplete.part');$classEnv=Read-Envelope (& $runtime -Command Scan -Source $classDir);$byName=@{};foreach($item in $classEnv.items){$byName[$item.Name]=$item};Assert ($classEnv.count -eq 11) 'Classify excludes partial download';Assert ($byName['app.exe'].Category -eq 'Software' -and $byName['doc.docx'].Category -eq 'Documents' -and $byName['sheet.xlsx'].Category -eq 'Documents' -and $byName['github-source.zip'].Category -eq 'SourceCode' -and $byName['archive.zip'].Category -eq 'Review' -and $byName['model.gguf'].Category -eq 'AIAssets' -and $byName['weights.safetensors'].Category -eq 'AIAssets' -and $byName['photo.png'].Category -eq 'Others' -and $byName['unknown.bin'].Category -eq 'Review') 'Classification mapping'
 $empty=Make-Fixture empty @();$root=Join-Path $base 'custom-root';$null=New-Item -ItemType Directory $root
 $planJson=& $runtime -Command Plan -Root $root -Source $classDir -PlanPath (Join-Path $base 'plan.json');$planEnv=Read-Envelope $planJson;Assert ($planEnv.count -eq 11 -and !(Test-Path (Join-Path $root '01-Software'))) 'Plan is read-only and count stable'
 $emptyPlan=Read-Envelope (& $runtime -Command Plan -Root $root -Source $empty -PlanPath (Join-Path $base 'empty-plan.json'));Assert ($emptyPlan.count -eq 0 -and $emptyPlan.items.Count -eq 0) 'Plan zero items'
 $report=Read-Envelope (& $runtime -Command Report -PlanPath (Join-Path $base 'empty-plan.json'));Assert ($report.count -eq 0 -and $report.totalBytes -eq 0) 'Report zero items and bytes'
 $json=(ConvertTo-Json -InputObject ([pscustomobject]@{schemaVersion=1;operation='Plan';success=$true;count=1;items=@([pscustomobject]@{Name='one.pdf';Source=(Join-Path $empty 'one.pdf');Destination=(Join-Path $root '04-Documents\one.pdf');Bytes=[long]7;Category='Documents'});errors=@()}) -Depth 6);$onePath=Join-Path $base 'one-plan.json';$json|Set-Content $onePath;$one=Read-Envelope (& $runtime -Command Report -PlanPath $onePath);Assert ($one.count -eq 1 -and $one.totalBytes -eq 7) 'Report one item and Int64 bytes'
 $denied=$false;try{& $runtime -Command Apply -Root $root -PlanPath $onePath}catch{$denied=$true};Assert $denied 'Apply denies without authorization'
 $integ=Make-Fixture integration @('move.pdf');$ip=Join-Path $base 'integration-plan.json';$pe=Read-Envelope (& $runtime -Command Plan -Root $root -Source $integ -PlanPath $ip);$ap=Read-Envelope (& $runtime -Command Apply -Root $root -PlanPath $ip -Authorize);Assert ($ap.count -eq 1 -and (Test-Path (Join-Path $root '04-Documents\move.pdf'))) 'Apply authorized isolated move';$again=Read-Envelope (& $runtime -Command Apply -Root $root -PlanPath $ip -Authorize);Assert (!$again.success -and $again.items[0].Status -eq 'Failed' -and (Test-Path (Join-Path $root '04-Documents\move.pdf'))) 'Repeat apply fails safely without damage';$le=Read-Envelope (& $runtime -Command Locate -Root $root -Query move);Assert ($le.count -eq 1) 'Locate finds archived file';$re=Read-Envelope (& $runtime -Command Report -PlanPath $ip);Assert ($re.count -eq 1 -and $re.organized -eq 1 -and (Get-Content -Raw $re.markdownPath).StartsWith('# Download Organizer report')) 'Report integrated apply and Markdown'
 $victim=Make-Fixture outside @('keep.pdf');$outsidePlan=Join-Path $base 'outside-plan.json';$badDoc=[pscustomobject]@{schemaVersion=1;operation='Plan';success=$true;count=1;items=@([pscustomobject]@{Name='keep.pdf';Source=(Join-Path $victim 'keep.pdf');Destination=(Join-Path $base 'escape.pdf');Bytes=[long]6;Category='Documents'});errors=@()};$badDoc|ConvertTo-Json -Depth 5|Set-Content $outsidePlan;$blocked=Read-Envelope (& $runtime -Command Apply -Root $root -PlanPath $outsidePlan -Authorize);Assert (!$blocked.success -and (Test-Path (Join-Path $victim 'keep.pdf')) -and !(Test-Path (Join-Path $base 'escape.pdf'))) 'Apply rejects outside-root destination and retains source'
 $known=& $runtime -Command InspectDownloads|ConvertFrom-Json;Assert ($known.success -and (Test-Path -LiteralPath $known.windowsDownloads)) 'Known Folder readonly lookup'
} catch { $script:fail++;Write-Host "ERROR $($_.Exception.Message)" -ForegroundColor Red } finally {Remove-Item -LiteralPath $base -Recurse -Force -ErrorAction SilentlyContinue}
Write-Host "RESULT total=$($script:pass+$script:fail+$script:skip) passed=$script:pass failed=$script:fail skipped=$script:skip"
if($script:fail){exit 1}
